def parse(fr, r0, c0, nrows, ncols, shape):
    A = fr.ascii.split('\n')
    cells, reads = {}, {}
    for i,(a,b) in shape.items():
        for j in range(a,b):
            blk = [A[r0+8*i+rr][c0+8*j:c0+8*j+6] for rr in range(6)]
            flat = ''.join(blk)
            if 'W' in flat or 'g' in flat:
                mark = blk[2][2]  # center 2x2 color
                m = [[blk[2*ii][2*jj] for jj in range(3)] for ii in range(3)]
                reads[(i,j)] = (mark, m)
            else:
                cells[(i,j)] = flat[3*6+3]
    return cells, reads, (r0,c0)

